import java.util.Scanner;

public class Main {
    // 砍一半：两头夹着找，每趟看正中间那一只，答「比了几次」；没找到答负数
    static int halfFind(int[] a, int n, int target) {
        int lo = 0;
        int hi = n - 1;
        int tries = 0;

        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            tries++;
            if (a[mid] == target) {
                return tries;
            } else if (a[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return -tries;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int target = sc.nextInt();
        int[] a = new int[64];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int times = halfFind(a, n, target);
        if (times < 0) {
            System.out.println("砍一半：没找到");
        } else {
            System.out.println("砍一半：比了 " + times + " 次");
        }
    }
}
